UPDATE T_CX_STOCK
SET IS_DELETE = 1,
    UPDATE_BY = #{updateBy},
    UPDATE_TIME = #{updateTime}
WHERE FACTORY_CODE = #{factoryCode}
  AND DATA_SOURCE = #{dataSource}
  AND IS_DELETE = 0

UPDATE T_CX_STOCK SET IS_DELETE = 1, UPDATE_BY = #{updateBy}, UPDATE_TIME = #{updateTime} WHERE ID IN
#{id}
AND IS_DELETE = 0

mapper.delete:
DELETE FROM T_CX_STOCK
WHERE FACTORY_CODE = #{factoryCode}
  AND DATA_SOURCE = #{dataSource}
